import numpy as np
from numpy.linalg import lstsq
best=[]
for b in np.linspace(0.1,3,59):
  for kind in ['exp','log','inv']:
    if kind=='exp': s=np.exp(-b*P)
    elif kind=='log': s=np.log(P+b)
    else: s=1/(P+b)
    base=[np.ones_like(P),P,P**2,t,t*P,t*P**2,t**2,t**2*P]
    A=np.column_stack(base+[s])
    c,_,_,_=lstsq(A,dP_dt,rcond=None)
    best.append((np.mean((A@c-dP_dt)**2)/np.var(dP_dt),kind,round(b,2)))
best.sort(); print(best[:6])
